func:
// Escreve o CSV filtrado (ATL, jan/2025) em disco para o KNIME o ler.
// /data/raw (contentor) = node-red/data/raw (no PC). Cria uma msg NOVA:
// nao altera a msg que segue para o MongoDB.
let csv;
try { csv = msg.payload[1].$set.csv; } catch (e) { csv = null; }
if (!csv) { node.error("CSV nao encontrado na mensagem", msg); return null; }
return { payload: csv, extraction_id: msg.extraction_id };

// Regista a execucao com sucesso em etl_logs (msg nova, sem alterar a original).
return { payload: [{
    source: "bts_transtats",
    flow: "voos",
    status: "ok",
    extraction_id: msg.extraction_id || "bts_2025_1_ATL",
    row_count: (msg.rowCount !== undefined) ? msg.rowCount : null,
    at: new Date().toISOString()
}] };
